package com.vandorlabs.client;
import com.vandorlabs.tiles.*;
import com.vandorlabs.blocks.ModBlocks;
import net.minecraft.nbt.*;
/** Actual standalone row saved/configuration normalization, including half-height capacity. */
public final class ScreenControlLegacyChecks {
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");int cases=0;
  for(int half=0;half<2;half++)for(int count=0;count<=10;count++)for(int kind=0;kind<16;kind++){
   TileEntityAnimatedScreenSelector owner=new TileEntityAnimatedScreenSelector();NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);net.minecraft.util.math.BlockPos pos=new net.minecraft.util.math.BlockPos(0,80,0);world.states.put(pos,(half==0?ModBlocks.ANIMATED_SCREEN_SELECTOR:ModBlocks.PROGRAMMABLE_INPUT).getDefaultState());owner.setWorld(world);owner.setPos(pos);world.tiles.put(pos,owner);RedstoneScreenContents contents=owner.redstoneScreen(0);NBTTagCompound input=input(count,kind);contents.readFromNBT(input);String text=canonical(contents.writeToNBT(new NBTTagCompound()))+canonical(contents.configuration())+RedstoneScreenContents.validConfiguration(input);hash.update(text.getBytes("UTF-8"));cases++;
  }StringBuilder out=new StringBuilder();for(byte b:hash.digest())out.append(String.format("%02x",b&255));if(!out.toString().equals("a2e06f4e901b2e7d6b88bcbc83fb4fefbc6f506db945ec70949ea75f0643c274"))throw new AssertionError("Actual controls changed "+out);System.out.println("Actual Screen controls reference PASS cases="+cases+" sha256="+out);}
 public static NBTTagCompound input(int count,int kind){NBTTagCompound root=new NBTTagCompound();root.setBoolean("Enabled",true);if(kind!=0)root.setString("Title",kind==1?"bad\u00a7title":kind==2?"": "Controls");NBTTagList rows=new NBTTagList();for(int i=0;i<count;i++){NBTTagCompound row=new NBTTagCompound();row.setString("Label",kind==3?" ":kind==4?"abcdefghijklmnopqrstuvwxy":kind==5?"bad\nlabel":" Row "+i+" ");row.setIntArray("RedstoneChannels",kind==6?new int[]{-1}:new int[]{32,31,32});row.setBoolean("Slider",kind==7||kind==8||kind==9);row.setBoolean("Pulse",kind==8||kind==10||kind==11);if(kind!=0){row.setInteger("Min",kind==9?15:kind==12?-1:0);row.setInteger("Max",kind==9?0:kind==13?99:15);}row.setIntArray("Levels",new int[]{kind==14?-1:6,kind==15?99:12});row.setInteger("Level",kind==14?-1:kind==15?99:7);row.setIntArray("LatchedChannels",new int[]{31,99});row.setBoolean("Active",true);row.setLong("PulseUntil",kind==11?-3:123);rows.appendTag(row);}root.setTag("Rows",rows);return root;}
 private static String canonical(NBTBase tag){if(tag instanceof NBTTagCompound){NBTTagCompound compound=(NBTTagCompound)tag;StringBuilder out=new StringBuilder("{");for(String key:new java.util.TreeSet<String>(compound.getKeySet()))out.append(key).append(':').append(canonical(compound.getTag(key))).append(';');return out.append('}').toString();}if(tag instanceof NBTTagList){NBTTagList list=(NBTTagList)tag;StringBuilder out=new StringBuilder("[");for(int i=0;i<list.tagCount();i++)out.append(canonical(list.get(i))).append(';');return out.append(']').toString();}return tag.toString();}
}
